declare
-- Anula transacciones de forma masiva
  l_total_g simple_integer := 0;
  l_total_d simple_integer := 0;

--   TD	10	140	2964
  cursor trx is --> por número de transaccion
    select *
      from kardex_d
     where exists (
       select 1
         from tmp_carga_data
        where kardex_d.cod_alm = tmp_carga_data.cod_alm
          and kardex_d.tp_transac = tmp_carga_data.tp_transac
          and kardex_d.serie = tmp_carga_data.serie
          and kardex_d.numero = tmp_carga_data.numero
          and kardex_d.cod_art = tmp_carga_data.cod_art
       )
     order by ing_sal desc;

begin
  for r in trx loop
    delete
      from kardex_d
     where cod_alm = r.cod_alm
       and tp_transac = r.tp_transac
       and serie = r.serie
       and numero = r.numero
       and cod_art = r.cod_art;

    l_total_d := l_total_d + sql%rowcount;
  end loop;

  -- que no tienen detalle pero si cabecera
--   delete
--     from kardex_g
--    where exists (
--      select 1
--        from tmp_carga_data
--       where kardex_g.cod_alm = tmp_carga_data.cod_alm
--         and kardex_g.tp_transac = tmp_carga_data.tp_transac
--         and kardex_g.serie = tmp_carga_data.serie
--         and kardex_g.numero = tmp_carga_data.numero
--      )
--      and not exists (
--      select *
--        from kardex_d
--       where kardex_g.cod_alm = kardex_d.cod_alm
--         and kardex_g.tp_transac = kardex_d.tp_transac
--         and kardex_g.serie = kardex_d.serie
--         and kardex_g.numero = kardex_d.numero
--      );

  l_total_g := l_total_g + sql%rowcount;

  dbms_output.put_line('total eliminado kardex_g >>>>> ' || l_total_g);
  dbms_output.put_line('total eliminado kardex_d >>>>> ' || l_total_d);
end;

-- que no tienen detalle pero si cabecera
delete
  from kardex_g
 where exists (
   select 1
     from tmp_carga_data
    where kardex_g.cod_alm = tmp_carga_data.cod_alm
      and kardex_g.tp_transac = tmp_carga_data.tp_transac
      and kardex_g.serie = tmp_carga_data.serie
      and kardex_g.numero = tmp_carga_data.numero
   )
   and not exists (
   select *
     from kardex_d
    where kardex_g.cod_alm = kardex_d.cod_alm
      and kardex_g.tp_transac = kardex_d.tp_transac
      and kardex_g.serie = kardex_d.serie
      and kardex_g.numero = kardex_d.numero
   );

